import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"NTRIP / RTK","description":"","frontmatter":{},"headers":[],"relativePath":"en/qgc-user-guide/settings_view/ntrip_rtk.md","filePath":"en/qgc-user-guide/settings_view/ntrip_rtk.md"}`),a={name:`en/qgc-user-guide/settings_view/ntrip_rtk.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="ntrip-rtk" tabindex="-1">NTRIP / RTK <a class="header-anchor" href="#ntrip-rtk" aria-label="Permalink to “NTRIP / RTK”">​</a></h1><p>Configure the built-in NTRIP client to stream RTCM correction data to the vehicle for centimeter-level RTK GPS positioning.</p><h2 id="connection-status" tabindex="-1">Connection Status <a class="header-anchor" href="#connection-status" aria-label="Permalink to “Connection Status”">​</a></h2><p>Shows the current NTRIP connection state (connected/connecting/disconnected) with message and byte counters, data rate, and a Connect/Disconnect button.</p><h2 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to “Server”">​</a></h2><ul><li><strong>Host address</strong> — NTRIP caster hostname or IP</li><li><strong>Server port</strong> — NTRIP caster port (default: 2101)</li><li><strong>Username</strong> — NTRIP account username</li><li><strong>Password</strong> — NTRIP account password (with show/hide toggle)</li><li><strong>Use TLS encryption</strong> — enable TLS for the NTRIP connection</li></ul><h2 id="mountpoint" tabindex="-1">Mountpoint <a class="header-anchor" href="#mountpoint" aria-label="Permalink to “Mountpoint”">​</a></h2><ul><li><strong>Mount Point</strong> — the NTRIP mountpoint to connect to</li><li><strong>Browse</strong> — fetch available mountpoints from the server and display them in a list with format, navigation system, country, bitrate, and distance information</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to “Options”">​</a></h2><ul><li><strong>RTCM Message Filter</strong> — whitelist of RTCM message types to forward (empty = forward all)</li></ul><h2 id="udp-forwarding" tabindex="-1">UDP Forwarding <a class="header-anchor" href="#udp-forwarding" aria-label="Permalink to “UDP Forwarding”">​</a></h2><ul><li><strong>UDP forward RTCM data</strong> — forward received RTCM data to another device via UDP</li><li><strong>UDP target address</strong> — destination IP for forwarded data</li><li><strong>UDP target port</strong> — destination port for forwarded data</li></ul><h2 id="udp-rtcm-input" tabindex="-1">UDP RTCM Input <a class="header-anchor" href="#udp-rtcm-input" aria-label="Permalink to “UDP RTCM Input”">​</a></h2><ul><li><strong>Enable UDP RTCM input</strong> — receive RTCM data from a UDP source instead of NTRIP</li><li><strong>UDP RTCM input port</strong> — port to listen on (default: 13320, range: 1024–65535)</li></ul>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};